parameters.jsCode:
// n8n Code node (typeVersion 2)
// Output: single item with only 4 specific fields

const msg = $input.first().json.message || {};
const caption = (msg.caption && msg.caption.trim()) || (msg.text && msg.text.trim()) || '';

function stripQuotesAndTrim(s) {
  if (typeof s !== 'string') return '';
  return s.replace(/^["']|["']$/g, '').trim();
}

// Updated Map: Focuses only on your 4 requirements
const aliasMap = {
  productName: ['product name', 'name'],
  productType: ['product type', 'type'],
  description: ['discription', 'description', 'desc'], // Added 'discription' to catch the typo
  displayMode: ['display mode', 'displaymode', 'mode']
};

const keyLookup = {};
for (const [canon, aliases] of Object.entries(aliasMap)) {
  aliases.forEach(a => keyLookup[a.toLowerCase()] = canon);
}

// Initializing only the requested fields
const parsed = {
  productName: '',
  productType: '',
  description: '',
  displayMode: 'product-only'
};

if (caption && typeof caption === 'string') {
  const lines = caption.replace(/\r/g, '').split('\n').map(l => l.trim()).filter(Boolean);
  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) continue;

    const rawKey = line.substring(0, colonIndex).trim().toLowerCase();
    const rawVal = line.substring(colonIndex + 1).trim();
    const mappedKey = keyLookup[rawKey];

    if (!mappedKey) continue;

    let cleanVal = stripQuotesAndTrim(rawVal);

    if (mappedKey === 'displayMode') {
      const v = cleanVal.toLowerCase();
      cleanVal = (v === 'on-model' || v === 'on model' || v === 'model') ? 'on-model' : 'product-only';
    }

    parsed[mappedKey] = cleanVal;
  }
}

// Fallback logic
if (!parsed.productName) parsed.productName = 'this piece';

// Return ONLY the parsed product
return [{ json: parsed }];

